"""Publish the manual Tech Core geometry review as an offline comparison."""
import argparse
import json
from pathlib import Path
from audit import OUT


def main():
    parser=argparse.ArgumentParser();parser.add_argument('--absolute',action='store_true');args=parser.parse_args()
    data=json.loads((OUT/'review.json').read_text())
    for row in data['views']:
        if not args.absolute:row['image']=str(Path(row['image']).relative_to(OUT))
    html='''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>
body{margin:0;font:14px var(--font-sans,system-ui);color:var(--foreground,#ddd);line-height:1.5}h2{margin:0;font-size:21px}p{margin:9px 0 15px}.muted{color:var(--muted-foreground,#999)}.controls{display:flex;flex-wrap:wrap;gap:10px;margin:16px 0}label{display:flex;align-items:center;gap:6px}select,button{font:inherit;color:inherit;background:var(--secondary,#333);border:1px solid var(--border,#555);border-radius:5px;padding:7px;max-width:100%}.stats{display:flex;gap:24px;margin:18px 0;flex-wrap:wrap}.stats b{display:block;font-size:25px}.stats small{color:var(--muted-foreground,#999)}.note{padding:16px;background:var(--secondary,#222);border-radius:var(--radius,8px);margin-bottom:14px}.wipe{position:relative;aspect-ratio:1;overflow:hidden}.wipe img{position:absolute;inset:0;width:100%;height:100%;object-fit:contain}.seam{position:absolute;top:0;bottom:0;width:2px;background:#e6a140}.tag{position:absolute;top:10px;background:#111d;color:white;font-size:11px;padding:5px 7px;border-radius:4px}.left{left:10px}.right{right:10px}.slider{display:flex;gap:10px;align-items:center;margin:10px 0}.slider input{flex:1;accent-color:#e6a140}.pair{display:grid;grid-template-columns:1fr 1fr;gap:12px}.pair img{display:block;width:100%}.hidden{display:none}details{font-size:13px;margin:14px 0}summary{cursor:pointer}table{border-collapse:collapse;width:100%}th,td{text-align:right;padding:7px;border-bottom:1px solid var(--border,#555)}th:first-child,td:first-child{text-align:left}.small{font-size:12px}button{cursor:pointer}@media(max-width:480px){select,label{font-size:12px}.stats{gap:15px}.stats b{font-size:21px}}
</style></head><body><h2>Tech Core · manual geometry review</h2><p class="muted">Further reductions from the reviewed 17 mm detail version. The crucial top geometry is restored exactly. The shield replacement and all associated deletions are withdrawn.</p>
<div class="controls"><label>Geometry <select id="role"><option value="visual">Visual</option><option value="collision">Collision</option></select></label><label>Trial <select id="trial"></select></label><label>Subject <select id="group"><option value="tool">Tool head</option><option value="whole">Whole Core</option><option value="arm">Arm</option><option value="pedestal">Pedestal</option></select></label><label>View <select id="view"><option value="oblique">Oblique</option><option value="reverse">Reverse</option><option value="front">Front</option><option value="back">Back</option><option value="side">Side</option><option value="top">Top</option><option value="bottom">Bottom</option></select></label><label>Layout <select id="layout"><option value="wipe">Wipe</option><option value="pair">Side by side</option></select></label></div>
<div class="stats"><div><small>Reviewed triangles / Core</small><b id="before"></b></div><div><small>Trial triangles / Core</small><b id="after"></b></div><div><small>Reduction</small><b id="percent"></b></div></div><div class="note" id="note"></div><p id="saving" class="small"></p>
<div id="wipe" class="wipe"><img id="base" alt="Reviewed baseline"><img id="candidate" alt="Manual simplification candidate"><div id="seam" class="seam"></div><span class="tag left">Reviewed baseline</span><span id="tag" class="tag right"></span></div><div class="pair hidden" id="pair"><div><img id="pb" alt="Reviewed baseline"><small>Reviewed baseline</small></div><div><img id="pa" alt="Candidate"><small id="caption"></small></div></div><div class="slider" id="slider"><small>Baseline</small><input id="position" type="range" min="0" max="100" value="50" aria-label="Comparison divider"><small>Trial</small></div>
<p class="small muted">Matched 1200 × 1200 source-color renders; seven rest-pose views. Colored target and LED geometry remain exact. These trials remain uninstalled. Motion, runtime PBR, projectile contacts and simulator speed have not been measured.</p>
<details><summary>Correction</summary><p>The top geometry was incorrectly identified as ventilation. It is crucial and is now protected in full. The restored baseline is byte-for-byte identical to the reviewed input. The independent arm-housing experiment remains separate; its tool head also matches that input exactly.</p></details>
<script>const data=__DATA__,$=id=>document.getElementById(id),fmt=n=>n.toLocaleString('en-US'),levels=new Map(data.levels.map(l=>[l.id,l])),views=new Map(data.views.map(r=>[[r.stage,r.group,r.view].join('|'),r]));if(views.size!==168)throw Error('Incomplete view matrix');const notes={vents:'Restored reviewed baseline: crucial top geometry and the entire tool head are unchanged. The former shield replacement and its enclosed-face deletions are withdrawn.',housings:'Independent visual arm-housing experiment only. The entire tool head, including the crucial top geometry, is unchanged.',combined:'Top geometry restored exactly; this now contains only the separate arm-housing experiment.'};function row(stage){return views.get([stage,$('group').value,$('view').value].join('|'))}function wipe(){const p=$('position').value;$('candidate').style.clipPath='inset(0 0 0 '+p+'%)';$('seam').style.left=p+'%'}function update(){const l=levels.get($('trial').value),b=levels.get(l.role+'-baseline'),r=row(l.id),br=row(b.id),policy=l.id.split('-').slice(1).join('-');$('base').src=$('pb').src=br.image;$('candidate').src=$('pa').src=r.image;$('tag').textContent=$('caption').textContent=l.label;$('before').textContent=fmt(b.triangles);$('after').textContent=fmt(l.triangles);$('percent').textContent=((1-l.triangles/b.triangles)*100).toFixed(1)+'%';$('note').textContent=notes[policy];$('saving').textContent=fmt(2*(b.triangles-l.triangles))+' fewer placed triangles across the two Tech Cores. Selected subject: '+fmt(br.triangles)+' → '+fmt(r.triangles)+'.';const pair=$('layout').value==='pair';$('wipe').classList.toggle('hidden',pair);$('pair').classList.toggle('hidden',!pair);$('slider').classList.toggle('hidden',pair);wipe()}function role(){const options=data.levels.filter(l=>l.role===$('role').value&&!l.baseline);$('trial').innerHTML=options.map(l=>'<option value="'+l.id+'">'+l.label+'</option>').join('');update()}$('role').onchange=role;for(const id of ['trial','group','view','layout'])$(id).onchange=update;$('position').oninput=wipe;$('candidate').onload=()=>console.log('Candidate '+$('candidate').naturalWidth+' × '+$('candidate').naturalHeight);role();console.log('Validated '+views.size+' matched comparisons');</script></body></html>'''.replace('__DATA__',json.dumps(data))
    (OUT/('review-inline.html'if args.absolute else'review.html')).write_text(html)


if __name__=='__main__':main()
